package pkgclass

import (
	"go/ast"
	"strings"
)

// MockFileName reports whether a file name follows mockgen's own output
// naming: `*_mock.go`, or the `zzz_` prefix some wrappers use. A name is a
// guess; MockHeader is the proof.
func MockFileName(path string) bool {
	base := path[strings.LastIndex(path, "/")+1:]
	return strings.HasSuffix(base, "_mock.go") || strings.HasPrefix(base, "zzz_")
}

// mockGenerators are the generator names that follow "Code generated by " in
// the header of a mock file. Each is matched as a whole word, so a version
// suffix ("mockery v2.43.0", "mockery;") is accepted and "mockeryfoo" is not.
var mockGenerators = []string{"MockGen", "mockery", "github.com/gojuno/minimock", "counterfeiter", "moq"}

// MockHeader reports whether the generated-code header of f names a mock
// generator: mockgen (golang/mock and uber/mock), mockery, minimock,
// counterfeiter or moq. The
// header is the "// Code generated ... DO NOT EDIT." line convention, read
// from the comments before the package clause only, so a doc comment that
// mentions mockgen in a hand-written file never counts. f must be parsed with
// comments; a nil f is not a mock.
func MockHeader(f *ast.File) bool {
	if f == nil {
		return false
	}
	const prefix = "// Code generated by "
	for _, group := range f.Comments {
		for _, c := range group.List {
			if c.Pos() > f.Package {
				return false // past the package clause
			}
			rest, ok := strings.CutPrefix(strings.TrimRight(c.Text, "\r"), prefix)
			if ok && strings.HasSuffix(rest, "DO NOT EDIT.") && mockGenerator(rest) {
				return true
			}
		}
	}
	return false
}

// mockGenerator reports whether the text after "Code generated by " starts
// with one of mockGenerators as a whole word.
func mockGenerator(rest string) bool {
	rest = strings.TrimPrefix(strings.TrimPrefix(rest, "http://"), "https://")
	for _, g := range mockGenerators {
		if r, ok := strings.CutPrefix(rest, g); ok && (r == "" || !isWordByte(r[0])) {
			return true
		}
	}
	return false
}

func isWordByte(b byte) bool {
	return b == '_' || b >= '0' && b <= '9' || b >= 'a' && b <= 'z' || b >= 'A' && b <= 'Z'
}
